html,
body {
    width: 85mm;
    margin: 0;
    padding: 0;
}

.ticket {
    width: 85mm;
    box-sizing: border-box;
}

hr {
    border: 0;
    border-top: 1px solid #000;
    margin: 0;
    padding: 0;
    height: 0;
}

.subtitle {
    font-size:10px;
}

.center {
    text-align: center;
}

.right {
    text-align: right;
}

.timestamp {
    font-size: 9px;
    padding-top: 5px;
}


.info-table,
.items-table {
    /*width: 100%;*/
    border-collapse: collapse;
    font-size: 8px;
}

.info-table td {
    padding: 0;
    vertical-align: top;
}

.info-table .label {
    width: 25%;
    font-weight: bold;
}

.items-table th {
    border-bottom: 1px solid #000;
    text-align: left;
    padding: 0;
}

.items-table td {
    padding: 2px 0;
    vertical-align: top;
}

.items-table th:nth-child(2),
.items-table th:nth-child(3),
.items-table th:nth-child(4),
.items-table td:nth-child(2),
.items-table td:nth-child(3),
.items-table td:nth-child(4) {
    text-align: center;
}
